import{_ as s,c as i,o as t,a9 as a,aq as r}from"./chunks/framework.BXLNC15u.js";const u=JSON.parse('{"title":"Create a Service","description":"Create the first PURISTA service","frontmatter":{"title":"Create a Service","description":"Create the first PURISTA service","order":103000,"image":"/graphic/add_service.png"},"headers":[],"relativePath":"handbook/1_quickstart/create-a-service.md","filePath":"handbook/1_quickstart/create-a-service.md","lastUpdated":1773313291000}'),n={name:"handbook/1_quickstart/create-a-service.md"};function h(o,e,c,l,d,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="create-the-first-service" tabindex="-1">Create the first service <a class="header-anchor" href="#create-the-first-service" aria-label="Permalink to “Create the first service”">​</a></h1><p><img src="'+r+'" alt="Add service with cli"></p><p>A service is a logical group of functions and subscriptions. This is where the business-driven aspect comes in. In our example, we will use the classic example - Users.</p><p>At the end, we want to have two business areas - <em>User</em> and <em>Email</em>. ... ? What is the name (or business area) of your new service (something like: user or account) ... They should reflect a single entity or business name. ... For example, if you have a business area <em>bank account</em>, you can simply type in <em>bank account</em>. The CLI tool will convert it to something like <em>bankAccount</em></p><p>After you have confirm your input by pressing the enter key, you will be asked for a short description of the service.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> What is the matter of service </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user&quot;</span></span></code></pre></div><p>Here, you should enter some short, general description, which will be used for some human-facing documentation. So, please provide here something like: <em>manages data related to users</em>.</p><p>In the last step, you will be asked for the version of your service. It defaults to <em>1</em>, which you can simply confirm by pressing the enter key. If you need to create a new version of an existing service, you can enter any integer number larger than <em>1</em>.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> number</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> of</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> this</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (1)</span></span></code></pre></div><p>Now, all files should be generated.</p><h2 id="start-the-service" tabindex="-1">Start the service <a class="header-anchor" href="#start-the-service" aria-label="Permalink to “Start the service”">​</a></h2><p>In PURISTA, services are defined by using service builders. Based on the service builder, an instance of the service can be created. This instance needs to be started. By starting the service, the service will connect to the eventbridge and start listening for events.</p>',12)])])}const m=s(n,[["render",h]]);export{u as __pageData,m as default};
